mapper.select:
SELECT DISTINCT u.username AS username, u.real_name AS real_name, u.wecom_userid AS wecom_userid FROM sys_user u JOIN sys_user_department ud ON ud.user_id = u.id AND ud.deleted = 0 JOIN sys_department d ON d.id = ud.department_id AND d.deleted = 0 WHERE u.deleted = 0 AND u.enabled = 1 AND u.tenant_id = #{tenantId} AND u.wecom_userid IS NOT NULL AND u.wecom_userid <> ''
AND d.id IN #{did}
AND (d.workbench_type = 'CS' OR d.name LIKE '%客服%')
